SELECT channel, CAST(dateTime AS DATE) AS day, count(*) AS total_bids, count(*) FILTER (WHERE price < 10000) AS rank1_bids, count(*) FILTER (WHERE price >= 10000 AND price < 1000000) AS rank2_bids, count(*) FILTER (WHERE price >= 1000000) AS rank3_bids, count(DISTINCT bidder) AS total_bidders, SUM(CASE WHEN price >= 1000000 THEN 1 ELSE 0 END) AS big_bids FROM bid GROUP BY channel, day ORDER BY total_bids DESC, channel, day LIMIT 100;
